/* ids are sorted ascending, so a binary search is the whole lookup. */
static int obj_index(int32_t id) {
    int lo = 0, hi = GM_OBJECT_COUNT - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        int32_t k = GM_OBJECTS[mid].id;
        if (k == id) return mid;
        if (k < id) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}

int gm_object_exists(int32_t id) { return obj_index(id) >= 0; }

/* The collision parent graph needs every declared object, not just the ones
 * the fixture happens to place, so expose the id roster. */
int32_t gm_object_id_at(int index) {
    return (index >= 0 && index < GM_OBJECT_COUNT) ? GM_OBJECTS[index].id : -1;
}

const char* gm_object_name(int32_t id) {
    int i = obj_index(id);
    return i >= 0 ? GM_OBJECTS[i].name : NULL;
}

int32_t gm_object_sprite(int32_t id) {
    int i = obj_index(id);
    return i >= 0 ? GM_OBJECTS[i].sprite : -1;
}

/* -1 covers both "no Create body" and "unknown object"; pair with
 * gm_object_exists() when the difference matters. */
int gm_object_create_code(int32_t id) {
    int i = obj_index(id);
    return i >= 0 ? GM_OBJECTS[i].create_code : -1;
}

int gm_object_parent_count(int32_t id) {
    int i = obj_index(id);
    return i >= 0 ? GM_OBJECTS[i].parent_count : 0;
}

int32_t gm_object_parent(int32_t id, int index) {
    int i = obj_index(id);
    if (i < 0 || index < 0 || index >= GM_OBJECTS[i].parent_count) return -1;
    return GM_OBJECT_PARENTS[GM_OBJECTS[i].parent_start + index];
}
